//! Wayland wire protocol, usable from both the server and the client side.
//!
//! Messages are decoded generically against the interface tables generated by
//! `build.rs`, and encoded with the [`Msg`] builder.

use std::collections::VecDeque;
use std::fmt;
use std::io;
use std::os::fd::{AsRawFd, FromRawFd, OwnedFd, RawFd};

mod protocols {
    use crate::Interface;
    include!(concat!(env!("OUT_DIR"), "/protocols.rs"));
}
pub use protocols::*;

pub struct Interface {
    pub name: &'static str,
    pub version: u32,
    pub requests: &'static [MessageDesc],
    pub events: &'static [MessageDesc],
}

impl fmt::Debug for Interface {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.name)
    }
}

pub fn interface_by_name(name: &str) -> Option<&'static Interface> {
    ALL.iter().copied().find(|i| i.name == name)
}

pub struct MessageDesc {
    pub name: &'static str,
    pub since: u32,
    pub destructor: bool,
    pub args: &'static [ArgDesc],
}

pub struct ArgDesc {
    pub name: &'static str,
    pub kind: ArgKind,
    pub interface: Option<&'static str>,
    pub nullable: bool,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ArgKind {
    Int,
    Uint,
    Fixed,
    Str,
    Object,
    NewId,
    Array,
    Fd,
}

/// A decoded argument. An untyped `new_id` expands to `Str`, `Uint`, `NewId`
/// (interface name, version, id), exactly as it travels on the wire.
#[derive(Debug)]
pub enum Arg {
    Int(i32),
    Uint(u32),
    Fixed(i32),
    Str(Option<String>),
    Object(u32),
    NewId(u32),
    Array(Vec<u8>),
    Fd(OwnedFd),
}

#[derive(Debug)]
pub struct Args(pub Vec<Arg>);

impl Args {
    pub fn int(&self, i: usize) -> i32 {
        match self.0[i] {
            Arg::Int(v) | Arg::Fixed(v) => v,
            Arg::Uint(v) => v as i32,
            _ => unreachable!("argument {i} is not an int"),
        }
    }

    pub fn uint(&self, i: usize) -> u32 {
        match self.0[i] {
            Arg::Uint(v) | Arg::Object(v) | Arg::NewId(v) => v,
            Arg::Int(v) => v as u32,
            _ => unreachable!("argument {i} is not a uint"),
        }
    }

    pub fn fixed(&self, i: usize) -> f64 {
        match self.0[i] {
            Arg::Fixed(v) => fixed_to_f64(v),
            _ => unreachable!("argument {i} is not fixed"),
        }
    }

    /// Object id; 0 means null.
    pub fn obj(&self, i: usize) -> u32 {
        self.uint(i)
    }

    pub fn str(&self, i: usize) -> Option<&str> {
        match &self.0[i] {
            Arg::Str(s) => s.as_deref(),
            _ => unreachable!("argument {i} is not a string"),
        }
    }

    pub fn array(&self, i: usize) -> &[u8] {
        match &self.0[i] {
            Arg::Array(a) => a,
            _ => unreachable!("argument {i} is not an array"),
        }
    }

    pub fn take_fd(&mut self, i: usize) -> OwnedFd {
        match std::mem::replace(&mut self.0[i], Arg::Uint(0)) {
            Arg::Fd(fd) => fd,
            _ => unreachable!("argument {i} is not an fd"),
        }
    }
}

pub fn fixed_to_f64(v: i32) -> f64 {
    v as f64 / 256.0
}

pub fn fixed_from_f64(v: f64) -> i32 {
    (v * 256.0).round() as i32
}

#[derive(Debug)]
pub enum DecodeError {
    Truncated,
    MissingFd,
    BadString,
    NullNotAllowed,
}

impl fmt::Display for DecodeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let s = match self {
            DecodeError::Truncated => "message truncated",
            DecodeError::MissingFd => "file descriptor missing",
            DecodeError::BadString => "malformed string",
            DecodeError::NullNotAllowed => "null value not allowed",
        };
        f.write_str(s)
    }
}

/// Decodes a message body (header excluded) according to its signature.
pub fn decode(desc: &MessageDesc, body: &[u8], fds: &mut VecDeque<OwnedFd>) -> Result<Args, DecodeError> {
    let mut pos = 0;
    let mut out = Vec::with_capacity(desc.args.len() + 2);
    let word = |pos: &mut usize| -> Result<u32, DecodeError> {
        let b = body.get(*pos..*pos + 4).ok_or(DecodeError::Truncated)?;
        *pos += 4;
        Ok(u32::from_ne_bytes(b.try_into().unwrap()))
    };
    let blob = |pos: &mut usize, len: usize| -> Result<&[u8], DecodeError> {
        let b = body.get(*pos..*pos + len).ok_or(DecodeError::Truncated)?;
        *pos += (len + 3) & !3;
        Ok(b)
    };
    let string = |pos: &mut usize| -> Result<Option<String>, DecodeError> {
        let len = word(pos)? as usize;
        if len == 0 {
            return Ok(None);
        }
        let b = blob(pos, len)?;
        let (last, s) = b.split_last().ok_or(DecodeError::BadString)?;
        if *last != 0 {
            return Err(DecodeError::BadString);
        }
        Ok(Some(String::from_utf8_lossy(s).into_owned()))
    };
    for a in desc.args {
        match a.kind {
            ArgKind::Int => out.push(Arg::Int(word(&mut pos)? as i32)),
            ArgKind::Uint => out.push(Arg::Uint(word(&mut pos)?)),
            ArgKind::Fixed => out.push(Arg::Fixed(word(&mut pos)? as i32)),
            ArgKind::Str => {
                let s = string(&mut pos)?;
                if s.is_none() && !a.nullable {
                    return Err(DecodeError::NullNotAllowed);
                }
                out.push(Arg::Str(s));
            }
            ArgKind::Object => {
                let id = word(&mut pos)?;
                if id == 0 && !a.nullable {
                    return Err(DecodeError::NullNotAllowed);
                }
                out.push(Arg::Object(id));
            }
            ArgKind::NewId => {
                if a.interface.is_none() {
                    let iface = string(&mut pos)?.ok_or(DecodeError::NullNotAllowed)?;
                    out.push(Arg::Str(Some(iface)));
                    out.push(Arg::Uint(word(&mut pos)?));
                }
                out.push(Arg::NewId(word(&mut pos)?));
            }
            ArgKind::Array => {
                let len = word(&mut pos)? as usize;
                out.push(Arg::Array(blob(&mut pos, len)?.to_vec()));
            }
            ArgKind::Fd => out.push(Arg::Fd(fds.pop_front().ok_or(DecodeError::MissingFd)?)),
        }
    }
    Ok(Args(out))
}

/// Builder for an outgoing message.
pub struct Msg {
    buf: Vec<u8>,
    fds: Vec<OwnedFd>,
}

impl Msg {
    pub fn new(object: u32, opcode: u16) -> Msg {
        let mut buf = Vec::with_capacity(32);
        buf.extend_from_slice(&object.to_ne_bytes());
        buf.extend_from_slice(&(opcode as u32).to_ne_bytes());
        Msg { buf, fds: Vec::new() }
    }

    pub fn uint(mut self, v: u32) -> Msg {
        self.buf.extend_from_slice(&v.to_ne_bytes());
        self
    }

    pub fn int(self, v: i32) -> Msg {
        self.uint(v as u32)
    }

    pub fn fixed(self, v: f64) -> Msg {
        self.int(fixed_from_f64(v))
    }

    /// Object or new_id argument; 0 means null.
    pub fn obj(self, id: u32) -> Msg {
        self.uint(id)
    }

    pub fn str(self, s: &str) -> Msg {
        self.opt_str(Some(s))
    }

    pub fn opt_str(mut self, s: Option<&str>) -> Msg {
        match s {
            None => self.uint(0),
            Some(s) => {
                self.buf.extend_from_slice(&(s.len() as u32 + 1).to_ne_bytes());
                self.buf.extend_from_slice(s.as_bytes());
                self.buf.push(0);
                self.pad();
                self
            }
        }
    }

    pub fn array(mut self, a: &[u8]) -> Msg {
        self.buf.extend_from_slice(&(a.len() as u32).to_ne_bytes());
        self.buf.extend_from_slice(a);
        self.pad();
        self
    }

    pub fn fd(mut self, fd: OwnedFd) -> Msg {
        self.fds.push(fd);
        self
    }

    fn pad(&mut self) {
        while !self.buf.len().is_multiple_of(4) {
            self.buf.push(0);
        }
    }
}

pub struct Header {
    pub object: u32,
    pub opcode: u16,
    pub size: usize,
}

const MAX_FDS_PER_MSG: usize = 28;
const MAX_BUFFERED: usize = 4 * 1024 * 1024;

/// A Wayland socket with its input and output buffers.
pub struct Connection {
    fd: OwnedFd,
    inbuf: Vec<u8>,
    infds: VecDeque<OwnedFd>,
    outbuf: Vec<u8>,
    outfds: VecDeque<OwnedFd>,
}

impl Connection {
    /// Takes ownership of a connected, non-blocking Unix stream socket.
    pub fn new(fd: OwnedFd) -> Connection {
        Connection { fd, inbuf: Vec::new(), infds: VecDeque::new(), outbuf: Vec::new(), outfds: VecDeque::new() }
    }

    pub fn raw_fd(&self) -> RawFd {
        self.fd.as_raw_fd()
    }

    /// Reads whatever is available. Returns `Ok(0)` on end of stream and
    /// `WouldBlock` when nothing is pending.
    pub fn fill(&mut self) -> io::Result<usize> {
        let mut data = [0u8; 16384];
        let mut cmsg = [0u64; 64];
        let mut iov = libc::iovec { iov_base: data.as_mut_ptr().cast(), iov_len: data.len() };
        let mut hdr: libc::msghdr = unsafe { std::mem::zeroed() };
        hdr.msg_iov = &mut iov;
        hdr.msg_iovlen = 1;
        hdr.msg_control = cmsg.as_mut_ptr().cast();
        hdr.msg_controllen = std::mem::size_of_val(&cmsg);
        let n = unsafe { libc::recvmsg(self.fd.as_raw_fd(), &mut hdr, libc::MSG_DONTWAIT | libc::MSG_CMSG_CLOEXEC) };
        if n < 0 {
            return Err(io::Error::last_os_error());
        }
        unsafe {
            let mut c = libc::CMSG_FIRSTHDR(&hdr);
            while !c.is_null() {
                if (*c).cmsg_level == libc::SOL_SOCKET && (*c).cmsg_type == libc::SCM_RIGHTS {
                    let len = (*c).cmsg_len as usize - libc::CMSG_LEN(0) as usize;
                    let p = libc::CMSG_DATA(c) as *const RawFd;
                    for i in 0..len / std::mem::size_of::<RawFd>() {
                        self.infds.push_back(OwnedFd::from_raw_fd(p.add(i).read_unaligned()));
                    }
                }
                c = libc::CMSG_NXTHDR(&hdr, c);
            }
        }
        self.inbuf.extend_from_slice(&data[..n as usize]);
        Ok(n as usize)
    }

    /// Header of the next complete message, if one is buffered.
    pub fn peek(&self) -> Option<Header> {
        if self.inbuf.len() < 8 {
            return None;
        }
        let object = u32::from_ne_bytes(self.inbuf[0..4].try_into().unwrap());
        let word = u32::from_ne_bytes(self.inbuf[4..8].try_into().unwrap());
        let size = (word >> 16) as usize;
        if self.inbuf.len() < size {
            return None;
        }
        Some(Header { object, opcode: word as u16, size })
    }

    /// Decodes the message announced by `peek` and removes it from the buffer.
    pub fn decode(&mut self, h: &Header, desc: &MessageDesc) -> Result<Args, DecodeError> {
        if h.size < 8 {
            return Err(DecodeError::Truncated);
        }
        let res = decode(desc, &self.inbuf[8..h.size], &mut self.infds);
        self.inbuf.drain(..h.size);
        res
    }

    /// Drops the message announced by `peek` without decoding it.
    pub fn skip(&mut self, h: &Header) {
        self.inbuf.drain(..h.size.max(8).min(self.inbuf.len()));
    }

    pub fn send(&mut self, mut msg: Msg) {
        let size = msg.buf.len() as u32;
        let word = u32::from_ne_bytes(msg.buf[4..8].try_into().unwrap());
        msg.buf[4..8].copy_from_slice(&((size << 16) | (word & 0xffff)).to_ne_bytes());
        self.outbuf.extend_from_slice(&msg.buf);
        self.outfds.extend(msg.fds);
    }

    pub fn has_pending_output(&self) -> bool {
        !self.outbuf.is_empty()
    }

    /// True when the peer stopped reading for too long.
    pub fn overflowed(&self) -> bool {
        self.outbuf.len() > MAX_BUFFERED
    }

    /// Writes as much as possible. Returns `Ok(true)` when everything is sent.
    pub fn flush(&mut self) -> io::Result<bool> {
        while !self.outbuf.is_empty() {
            let nfds = self.outfds.len().min(MAX_FDS_PER_MSG);
            let raw: Vec<RawFd> = self.outfds.iter().take(nfds).map(|f| f.as_raw_fd()).collect();
            let mut cmsg = [0u64; 32];
            let mut iov = libc::iovec { iov_base: self.outbuf.as_ptr() as *mut _, iov_len: self.outbuf.len() };
            let mut hdr: libc::msghdr = unsafe { std::mem::zeroed() };
            hdr.msg_iov = &mut iov;
            hdr.msg_iovlen = 1;
            if nfds > 0 {
                let bytes = (nfds * std::mem::size_of::<RawFd>()) as u32;
                hdr.msg_control = cmsg.as_mut_ptr().cast();
                hdr.msg_controllen = unsafe { libc::CMSG_SPACE(bytes) } as usize;
                unsafe {
                    let c = libc::CMSG_FIRSTHDR(&hdr);
                    (*c).cmsg_level = libc::SOL_SOCKET;
                    (*c).cmsg_type = libc::SCM_RIGHTS;
                    (*c).cmsg_len = libc::CMSG_LEN(bytes) as usize;
                    std::ptr::copy_nonoverlapping(raw.as_ptr(), libc::CMSG_DATA(c) as *mut RawFd, nfds);
                }
            }
            let n = unsafe { libc::sendmsg(self.fd.as_raw_fd(), &hdr, libc::MSG_DONTWAIT | libc::MSG_NOSIGNAL) };
            if n < 0 {
                let e = io::Error::last_os_error();
                if e.kind() == io::ErrorKind::WouldBlock {
                    return Ok(false);
                }
                return Err(e);
            }
            self.outfds.drain(..nfds);
            self.outbuf.drain(..n as usize);
        }
        Ok(true)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tables_are_generated() {
        let s = interface_by_name("wl_surface").unwrap();
        assert_eq!(s.requests[wl_surface::req::ATTACH as usize].name, "attach");
        assert_eq!(xdg_toplevel::state::ACTIVATED, 4);
        assert_eq!(wl_output::transform::_90, 1);
    }

    #[test]
    fn roundtrip_untyped_new_id() {
        let msg = Msg::new(2, wl_registry::req::BIND).uint(7).str("wl_seat").uint(5).obj(9);
        let body = &msg.buf[8..];
        let desc = &wl_registry::INTERFACE.requests[wl_registry::req::BIND as usize];
        let args = decode(desc, body, &mut VecDeque::new()).unwrap();
        assert_eq!(args.uint(0), 7);
        assert_eq!(args.str(1), Some("wl_seat"));
        assert_eq!(args.uint(2), 5);
        assert_eq!(args.uint(3), 9);
    }
}
